    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose p, q so that p+q is reasonably large
def gcd(a,b):
    while b:
        a,b = b,a%b
    return a
while True:
    p = rng.randint(2, 12)
    q = rng.randint(2, 12)
    if p + q < 5:
        continue
    # choose lambda as a reduced fraction in (0.2, 0.85)
    den = rng.randint(7, 20)
    num = rng.randint(2, den - 2)
    g = gcd(num, den)
    num //= g
    den //= g
    lam = num / den
    if not (0.2 < lam < 0.85):
        continue
    # compute S = (p+q)/sqrt(3) + lam/sqrt(1 - lam^2)
    K = p + q
    import math
    S = K / math.sqrt(3) + lam / math.sqrt(1 - lam**2)
    # sanity checks
    if not (S > 0 and math.isfinite(S)):
        continue
    a_const = p*p
    b_const = q*q
    return {
        'a_const': a_const,
        'b_const': b_const,
        'lam_num': num,
        'lam_den': den,
        's_total': float(S)
    }

